adding:35px;color:var(--muted)}dialog{border:0;border-radius:14px;padding:0;width:min(620px,94vw);box-shadow:0 20px 60px #10182855}dialog::backdrop{background:#10182888}.modal{padding:20px}.form{display:grid;grid-template-columns:1fr 1fr;gap:13px}.field{display:flex;flex-direction:column;gap:5px}.field.full{grid-column:1/-1}input,select{padding:10px;border:1px solid #cfd6e3;border-radius:8px}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.notice{padding:12px;border-radius:9px;background:#fffaeb;color:var(--warn);margin:12px 0}.error{background:#fef3f2;color:var(--bad)}.toast-region{position:fixed;right:20px;top:20px;z-index:9999;display:grid;gap:9px;width:min(390px,calc(100vw - 28px))}.toast{background:#fff;border:1px solid var(--line);border-left:4px solid var(--brand);border-radius:10px;padding:12px 14px;box-shadow:0 12px 35px #10182833;animation:toastIn .18s ease-out}.toast.ok{border-left-color:var(--ok)}.toast.error{border-left-color:var(--bad)}.toast b{display:block;margin-bottom:2px}.toast p{margin:0;color:var(--muted)}#networkActivity{position:fixed;left:50%;top:14px;transform:translateX(-50%);z-index:9998;background:#172033;color:#fff;border-radius:999px;padding:8px 13px;box-shadow:0 8px 25px #10182833;align-items:center;gap:8px}#networkActivity:not([hidden]){display:flex}.spinner{width:15px;height:15px;border:2px solid #ffffff55;border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite}.btn[disabled]{opacity:.62;cursor:wait}.btn:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #1677ff55;outline-offset:2px}.phone-preview{background:#dfe9f2;border-radius:22px;padding:16px;max-height:65vh;overflow:auto}.bot-bubble{background:#fff;border-radius:14px 14px 14px 4px;padding:11px 13px;margin:8px 34px 8px 0;box-shadow:0 1px 3px #10182822;white-space:pre-wrap}.bot-options{display:flex;gap:6px;flex-wrap:wrap;margin:0 34px 14px 0}.bot-options span{background:#e8f3ff;color:#075aaa;border:1px solid #b8d8fb;border-radius:9px;padding:7px 10px}.preview-meta{color:#475467;font-size:12px;margin-bottom:10px}.dialog-close{position:absolute;right:12px;top:12px;width:36px;height:36px;border:1px solid var(--line);border-radius:50%;background:#fff;font-size:20px;cursor:pointer;z-index:2}dialog{position:relative}.editor-workspace{width:min(1500px,98vw);height:94vh;max-width:none}.editor-workspace .modal{height:100%;display:flex;flex-direction:column}.editor-workspace #fieldEditor{max-height:none!important;flex:1;overflow:auto;padding-right:8px}.editor-workspace .formField{padding:18px}.editor-workspace .actions{position:sticky;bottom:0;background:#fff;padding:14px 0 4px;border-top:1px solid var(--line)}@keyframes spin{to{transform:rotate(360deg)}}@keyframes toastIn{from{opacity:0;transform:translateY(-8px)}}@media(prefers-reduced-motion:reduce){.toast,.spinner{animation:none}}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.wrap{padding:14px;display:block}.form{grid-template-columns:1fr}.tabs{position:static;display:flex;flex-direction:row;overflow:auto;margin:16px 0;padding:7px}.tab{width:auto;white-space:nowrap}.panel{margin-top:0}.editor-workspace{width:100vw;height:100vh;border-radius:0}}
