<?php if($canManage):?><dialog id="operatorDialog"><form class="modal" id="operatorForm"><h2 id="operatorHeading">Link Telegram operator</h2><input type="hidden" name="action" value="operator_save"><input type="hidden" name="id" value="0"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><div class="form"><label class="field full">Numeric Telegram user ID<input name="telegram_user_id" inputmode="numeric" pattern="[0-9]+" required></label><label class="field full">Active system account<select name="linked_user_id" id="linkedUserSelect" required><option value="">Loading eligible accounts…</option></select></label><label class="field">Status<select name="operator_status"><option value="active">Active</option><option value="suspended">Suspended</option><option value="revoked">Revoked</option></select></label><label class="field">Daily draft limit<input type="number" name="daily_registration_limit" min="1" max="200" value="50"></label><label><input type="checkbox" name="can_waiting" value="1" checked> Temporary/waiting</label><label><input type="checkbox" name="can_direct" value="1"> Direct registration</label><label><input type="checkbox" name="can_transfer" value="1"> Transfer registration</label></div><div class="actions"><button type="button" class="btn" id="cancelOperator">Cancel</button><button class="btn primary">Save operator</button></div></form></dialog><dialog id="formDialog" class="editor-workspace"><form class="modal" id="formEditor"><h2 id="formHeading">Edit form draft</h2><input type="hidden" name="id"><div class="form"><label class="field full">የቅጹ ርዕስ<input name="title_am" maxlength="150" required></label><input type="hidden" name="title_en"></div><div id="fieldEditor" style="max-height:55vh;overflow:auto;margin-top:14px"></div><div class="actions"><button type="button" class="btn" id="cancelForm">Cancel</button><button type="button" class="btn" id="previewForm">Preview conversation</button><button type="button" class="btn" id="publishForm">Publish</button><button class="btn primary">Save draft</button></div></form></dialog><dialog id="formPreviewDialog"><div class="modal"><h2>Telegram conversation preview</h2><div class="preview-meta" id="formPreviewMeta"></div><div class="phone-preview" id="formPreviewBody"></div><div class="actions"><button type="button" class="btn primary" id="closeFormPreview">Close preview</button></div></div></dialog><?php endif;?><?php if(!$isSetup):?><dialog id="batchDialog"><form class="modal" id="batchForm"><h2>Batch approval</h2><p class="hint" id="batchSelectionSummary"></p><label class="field">Approval note<input name="note" maxlength="1000" required></label><div class="actions"><button type="button" class="btn" id="cancelBatch">Cancel</button><button class="btn primary">Approve preflight-ready records</button></div></form></dialog><dialog id="reviewDialog"><div class="modal"><h2>HR review draft</h2><div id="reviewMeta" class="hint"></div><h3>Answers</h3><div id="reviewAnswers" class="tablebox"></div><h3>Duplicate candidates</h3><div id="reviewDuplicates"></div><h3>Review history</h3><div id="reviewHistory"></div><h3>Approval readiness</h3><div id="approvalReadiness"></div><form id="reviewForm"><input type="hidden" name="id"><label class="field">Decision<select name="decision" required><option value="">Choose…</option><option value="changes_requested">Request changes</option><option value="rejected">Reject</option><option value="duplicate">Mark duplicate</option></select></label><div id="correctionFieldPicker" class="card" style="margin-top:9px" hidden><b>Answers requiring correction</b><div class="hint">Select only the answers the registrar must update.</div><div id="correctionFieldOptions" style="display:grid;gap:6px;margin-top:8px"></div></div><label class="field" style="margin-top:9px">Required review note<input name="note" maxlength="1000" required></label><div class="actions"><button type="button" class="btn" id="closeReview">Close</button><button type="button" class="btn primary" id="approveReview">Approve and create record</button><button class="btn" id="saveReview">Record decision</button></div></form></div></dialog><?php endif;?>
<script src="/admin/js/danger_confirm.js?v=20261022dc4"></script><script>
const API='api_telegram_registration.php', CSRF=<?=json_encode($csrf)?>; const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let pendingRequests=0;function networkBusy(active){pendingRequests=Math.max(0,pendingRequests+(active?1:-1));document.getElementById('networkActivity').hidden=pendingRequests===0}function notify(message,type='ok',title='Done'){const region=document.getElementById('toastRegion'),toast=document.createElement('div');toast.className=`toast ${type}`;toast.innerHTML=`<b>${esc(title)}</b><p>${esc(message)}</p>`;region.appendChild(toast);setTimeout(()=>toast.remove(),5200)}async function api(action,options={}){const q=options.query?'&'+new URLSearchParams(options.query):'',controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000),trigger=document.activeElement instanceof HTMLButtonElement?document.activeElement:null;if(trigger){trigger.disabled=true;trigger.setAttribute('aria-busy','true')}networkBusy(true);try{const r=await fetch(`${API}?action=${encodeURIComponent(action)}${q}`,{credentials:'same-origin',...options,signal:options.signal||controller.signal});const j=await r.json().catch(()=>({status:'error',message:'The server returned an unreadable response. Reload and try again.'}));if(!r.ok||j.status!=='success')throw new Error(j.message||'The request could not be completed.');return j}catch(error){if(error.name==='AbortError')throw new Error('The server took too long to respond. Check your connection and try again.');throw error}finally{clearTimeout(timer);networkBusy(false);if(trigger){trigger.disabled=false;trigger.removeAttribute('aria-busy')}}}
function rows(id,data,render,span){document.getElementById(id).innerHTML=data.length?data.map(render).join(''):`<tr><td colspan="${span}" class="empty">No records found.</td></tr>`}
function showError(e){const message=e&&e.message?e.message:'Something went wrong. Please try again.';notify(message,'error','Action failed')}async function tgConfirm(options){if(!(window.DangerConfirm&&window.DangerConfirm.ask)){showError(new Error('The confirmation dialog did not load. Reload and retry.'));return false}return !!(await window.DangerConfirm.ask(options))}
async function loadOverview(){const j=await api('overview'),metrics=document.getElementById('metrics'),s=j.stats;if(metrics)metrics.innerHTML=[['Operators',s.operators],['Active',s.active_operators],['Open sessions',s.open_sessions],['Submitted drafts',s.submitted],['Failed updates (24h)',s.failed_updates_24h]].map(x=>`<div class="card metric"><b>${esc(x[1])}</b><span>${esc(x[0])}</span></div>`).join('');const checks=[['Migration 080',j.available],['Feature enabled',j.feature_enabled],['Bot token configured',j.secrets.bot_token],['Webhook secret configured',j.secrets.webhook_secret],['Canonical columns',j.canonical_columns],['Approval migration 083',j.approval_schema]];document.getElementById('health').innerHTML=checks.map(x=>`<span class="pill ${x[1]?'ok':'bad'}">${x[1]?'✓':'×'} ${esc(x[0])}</span>`).join('');const toggle=document.getElementById('featureToggle');if(toggle){toggle.dataset.enabled=j.feature_enabled?'1':'0';toggle.setAttribute('aria-pressed',j.feature_enabled?'true':'false');toggle.textContent=j.feature_enabled?'Disable Telegram registration':'Enable Telegram registration';toggle.classList.toggle('primary',!j.feature_enabled)}}
<?php if(!$isSetup):?>let operatorCache=[];async function loadOperators(){const j=await api('operators');operatorCache=j.operators;rows('operatorRows',j.operators,r=>`<tr><td>${esc(r.telegram_user_id)}</td><td>${esc(r.display_name||'Pending first contact')}</td><td>${esc(r.linked_user_name||r.linked_username||'—')}</td><td>${esc(r.linked_role||'—')}</td><td>${esc(r.status)}</td><td>${r.can_waiting==1?'Waiting ':''}${r.can_direct==1?'Direct ':''}${r.can_transfer==1?'Transfer':''}</td><td>${esc(r.last_seen_at||'Never')}</td><td><button class="btn editOperator" data-id="${Number(r.id)}">Edit</button></td></tr>`,8);document.querySelectorAll('.editOperator').forEach(b=>b.onclick=()=>openOperator(Number(b.dataset.id)).catch(showError))}
async function loadForms(){const j=await api('forms');rows('formRows',j.forms,r=>`<tr><td>${esc(r.profile_key)}</td><td>${esc(r.version)}</td><td>${esc(r.status)}</td><td>${esc(r.title_am)}</td><td>${esc(r.title_en)}</td><td>${esc(r.enabled_count)}/${esc(r.field_count)}</td><td>${esc(r.required_count)}</td><td>${r.status==='draft'&&<?=json_encode($canManage)?>?`<button class="btn editForm" data-id="${Number(r.id)}">Edit</button>`:'Immutable'}</td></tr>`,8);document.querySelectorAll('.editForm').forEach(b=>b.onclick=()=>openForm(Number(b.dataset.id)).catch(showError))}
async function loadSessions(){const status=document.getElementById('sessionStatus').value;const j=await api('sessions',{query:{status}});rows('sessionRows',j.sessions,r=>`<tr><td><input type="checkbox" class="sessionSelect" value="${Number(r.id)}" ${r.status==='submitted'?'':'disabled'}></td><td><b>${esc(r.member_name||'—')}</b><div class="hint">${esc(r.public_id)}</div></td><td>${esc(r.baptismal_name||'—')}</td><td>${esc(r.dob_ec||'—')}</td><td>${esc(r.current_section||'—')}</td><td>${esc(r.profile_key||'—')}</td><td>${esc(r.status)}</td><td>${esc(r.duplicate_state)}</td><td>${esc(r.operator_name||r.telegram_user_id)}</td><td>${esc(r.updated_at)}</td><td><button class="btn viewSession" data-id="${Number(r.id)}">Review</button></td></tr>`,11);document.querySelectorAll('.viewSession').forEach(b=>b.onclick=()=>openReview(Number(b.dataset.id)).catch(showError))}
async function loadAnalytics(){const days=document.getElementById('analyticsDays').value,j=await api('analytics',{query:{days}}),s=j.summary;document.getElementById('analyticsMetrics').innerHTML=[['Registrations',s.total],['Pending approval',s.pending],['Approved',s.approved],['Duplicate attention',s.duplicate_attention]].map(x=>`<div class="card metric"><b>${esc(x[1]||0)}</b><span>${esc(x[0])}</span></div>`).join('');const bars=items=>items.length?items.map(x=>`<div style="display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:9px 0"><span>${esc(x.label)}</span><b>${esc(x.total)}</b></div>`).join(''):'<div class="empty">No data for this period.</div>';document.getElementById('analyticsTypes').innerHTML=bars(j.registration_types);document.getElementById('analyticsOperators').innerHTML=bars(j.operators)}async function loadAudit(){const j=await api('audit');rows('auditRows',j.audit,r=>`<tr><td>${esc(r.created_at)}</td><td>${esc(r.actor_type)} #${esc(r.actor_id||'—')}</td><td>${esc(r.event)}</td><td>${esc(r.entity_type||'—')} #${esc(r.entity_id||'—')}</td><td>${esc(r.result)}</td></tr>`,5)}
const reviewDlg=document.getElementById('reviewDialog'),reviewForm=document.getElementById('reviewForm');async function openReview(id){const j=await api('session_detail',{query:{id}}),s=j.session;reviewForm.reset();reviewForm.elements.namedItem('id').value=id;document.getElementById('reviewMeta').textContent=`${s.public_id} • ${s.profile_key||'unselected'} v${s.form_version||'—'} • ${s.status} • operator ${s.operator_name||s.telegram_user_id}`;document.getElementById('reviewAnswers').innerHTML=`<table class="table"><tbody>${j.answers.map(a=>`<tr><th>${esc(a.label||a.field_key)}</th><td>${esc(a.value_text||'—')}</td></tr>`).join('')}</tbody></table>`;document.getElementById('correctionFieldOptions').innerHTML=j.answers.map(a=>`<label><input type="checkbox" value="${esc(a.field_key)}"> ${esc(a.label||a.field_key)} — ${esc(a.value_text||'Skipped')}</label>`).join('');const picker=document.getElementById('correctionFieldPicker'),decision=reviewForm.elements.namedItem('decision');decision.onchange=()=>picker.hidden=decision.value!=='changes_requested';picker.hidden=decision.value!=='changes_requested';document.getElementById('reviewDuplicates').innerHTML=j.duplicate_candidates.length?j.duplicate_candidates.map(c=>`<div class="card" style="margin-bottom:8px"><b>${esc(c.full_name||c.member_code||'Candidate')}</b> — score ${esc(c.match_score)}<div class="hint">${esc((c.match_reasons||[]).join('; '))}</div></div>`).join(''):'<div class="empty">No stored candidate snapshot.</div>';document.getElementById('reviewHistory').innerHTML=j.reviews.length?`<div class="card tablebox"><table class="table"><thead><tr><th>Revision</th><th>Decision</th><th>Reviewer</th><th>Note</th><th>Time</th></tr></thead><tbody>${j.reviews.map(r=>`<tr><td>${Number(r.session_revision)}</td><td>${esc(r.decision)}</td><td>${esc(r.reviewer_name||`User #${r.reviewer_user_id}`)}</td><td style="white-space:normal;min-width:180px">${esc(r.note||'—')}</td><td>${esc(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No review decisions yet.</div>';const readiness=j.approval_readiness,readinessItems=[...readiness.blockers.map(x=>`<li>${esc(x)}</li>`),...readiness.warnings.map(x=>`<li>${esc(x)}</li>`)];document.getElementById('approvalReadiness').innerHTML=`<div class="card"><span class="pill ${readiness.ready?'ok':'bad'}">${readiness.ready?'Preflight ready':'Approval blocked'}</span>${readinessItems.length?`<ul>${readinessItems.join('')}</ul>`:'<p class="hint">All current preflight checks passed.</p>'}<p class="hint">Approval is enabled only when all blocking preflight checks pass.</p></div>`;const approveButton=document.getElementById('approveReview');approveButton.disabled=!readiness.ready;approveButton.hidden=s.status!=='submitted'||Number(s.review_revision||0)>=Number(s.revision_number||1);if(j.candidate_cap_reached)document.getElementById('reviewDuplicates').insertAdjacentHTML('beforeend',`<div class="notice">Showing the safest ${Number(j.candidate_cap)} candidates from ${Number(j.plausible_count)} plausible matches. Verify DOB or phone to refine; results are never silently expanded into a broad member search.</div>`);reviewForm.style.display=s.status==='submitted'&&Number(s.review_revision||0)<Number(s.revision_number||1)?'block':'none';if(s.review_decision&&Number(s.review_revision||0)>=Number(s.revision_number||1))document.getElementById('reviewDuplicates').insertAdjacentHTML('beforebegin',`<div class="notice">Decision: ${esc(s.review_decision)} — ${esc(s.review_note||'')}</div>`);reviewDlg.showModal()}document.getElementById('closeReview').onclick=()=>reviewDlg.close();document.getElementById('approveReview').onclick=async()=>{const note=reviewForm.elements.namedItem('note').value.trim();if(!note){showError(new Error('Enter an approval note before approving.'));return}if(!(await tgConfirm({tier:'high',title:'Approve and create this registration record?',summary:'This permanently creates one member record from the submitted Telegram draft.',intent:'I verified the answers and duplicate results',consequences:['A waiting or permanent member record is created according to the draft profile.','This draft cannot create another member.'],keeps:['The draft, revisions, and review history remain audit linked.'],confirmLabel:'Approve and create'})))return;try{const body=new FormData();body.set('action','review_approve');body.set('csrf_token',CSRF);body.set('id',reviewForm.elements.namedItem('id').value);body.set('note',note);const result=await api('review_approve',{method:'POST',body});reviewDlg.close();notify(result.already_approved?'This draft was already approved; no duplicate record was created.':'Registration approved and record created.');if(result.notification_warning)notify(result.notification_warning,'error','Notification not delivered');await loadSessions()}catch(x){showError(x)}};reviewForm.onsubmit=async e=>{e.preventDefault();if(!(await tgConfirm({tier:'medium',title:'Record this review decision?',summary:'The decision is final in this review interface and is audit logged.',intent:'I reviewed this registration draft',consequences:['The submitted draft receives the selected HR decision.','The decision and note cannot be replaced here.'],keeps:['No member is created.','The original submitted answers remain available for audit.'],confirmLabel:'Record decision'})))return;try{const body=new FormData(e.target);body.set('action','review_decide');body.set('csrf_token',CSRF);body.set('correction_fields',JSON.stringify([...document.querySelectorAll('#correctionFieldOptions input:checked')].map(x=>x.value)));const result=await api('review_decide',{method:'POST',body});reviewDlg.close();notify('The HR decision was saved and audit logged.');if(result.notification_warning)notify(result.notification_warning,'error','Notification not delivered');else notify('The Telegram operator was notified.','ok','Message sent');await loadSessions()}catch(x){showError(x)}};
const loaders={overview:loadOverview,operators:loadOperators,forms:loadForms,sessions:loadSessions,analytics:loadAnalytics,audit:loadAudit};document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab,.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active');loaders[b.dataset.tab]().catch(showError)});document.getElementById('sessionStatus').onchange=()=>loadSessions().catch(showError);document.getElementById('analyticsDays').onchange=()=>loadAnalytics().catch(showError);const batchDlg=document.getElementById('batchDialog'),batchForm=document.getElementById('batchForm');document.getElementById('batchApprove').onclick=()=>{const ids=[...document.querySelectorAll('.sessionSelect:checked')].map(x=>Number(x.value));if(!ids.length){showError(new Error('Select at least one submitted registration.'));return}document.getElementById('batchSelectionSummary').textContent=`${ids.length} registration(s) selected. Blocked records will be skipped and reported.`;batchForm.dataset.ids=JSON.stringify(ids);batchDlg.showModal()};document.getElementById('cancelBatch').onclick=()=>batchDlg.close();batchForm.onsubmit=async e=>{e.preventDefault();if(!(await tgConfirm({tier:'high',title:'Approve selected registrations?',summary:'Only records passing all current preflight and duplicate checks will be created.',intent:'I reviewed the selected registration records',consequences:['Each ready draft creates one member record.','Blocked or concurrently changed drafts are skipped.'],keeps:['No draft can create more than one member.'],confirmLabel:'Approve ready records'})))return;try{const body=new FormData(e.target);body.set('action','review_batch_approve');body.set('csrf_token',CSRF);body.set('ids_json',e.target.dataset.ids);const j=await api('review_batch_approve',{method:'POST',body});batchDlg.close();notify(`${j.approved.length} approved; ${j.skipped.length} skipped.`,'ok','Batch complete');if(j.skipped.length)notify(j.skipped.map(x=>`#${x.session_id}: ${x.reason}`).join(' | '),'error','Skipped records');await loadSessions()}catch(x){showError(x)}};
<?php if($canManage):?>const dlg=document.getElementById('operatorDialog'),operatorForm=document.getElementById('operatorForm'),linkedUserSelect=document.getElementById('linkedUserSelect');async function loadEligibleUsers(selected=''){const j=await api('eligible_users');linkedUserSelect.innerHTML='<option value="">Choose an active account…</option>'+j.users.map(u=>`<option value="${Number(u.id)}" ${String(u.id)===String(selected)?'selected':''}>${esc(u.full_name||u.username)} — ${esc(u.role)} (#${Number(u.id)})</option>`).join('')}async function openOperator(id=0){await loadEligibleUsers();operatorForm.reset();operatorForm.elements.namedItem('id').value=id;document.getElementById('operatorHeading').textContent=id?'Edit Telegram operator':'Link Telegram operator';if(id){const r=operatorCache.find(x=>Number(x.id)===id);if(!r)throw new Error('Operator was not found.');operatorForm.elements.namedItem('telegram_user_id').value=r.telegram_user_id;linkedUserSelect.value=r.linked_user_id||'';operatorForm.elements.namedItem('operator_status').value=r.status;operatorForm.elements.namedItem('daily_registration_limit').value=r.daily_registration_limit;operatorForm.elements.namedItem('can_waiting').checked=Number(r.can_waiting)===1;operatorForm.elements.namedItem('can_direct').checked=Number(r.can_direct)===1;operatorForm.elements.namedItem('can_transfer').checked=Number(r.can_transfer)===1}dlg.showModal()}document.getElementById('addOperator').onclick=()=>openOperator().catch(showError);document.getElementById('cancelOperator').onclick=()=>dlg.close();operatorForm.onsubmit=async e=>{e.preventDefault();try{const body=new FormData(e.target);await api('operator_save',{method:'POST',body});dlg.close();e.target.reset();notify('Telegram operator access was saved.');await loadOperators()}catch(x){showError(x)}};const formDlg=document.getElementById('formDialog'),formEditor=document.getElementById('formEditor');let registry={};async function openForm(id){const [detail,reg]=await Promise.all([api('form_detail',{query:{id}}),api('form_registry')]);registry=reg.fields;const f=detail.form;formEditor.elements.namedItem('id').value=f.id;formEditor.elements.namedItem('title_am').value=f.title_am;formEditor.elements.namedItem('title_en').value=f.title_en;document.getElementById('formHeading').textContent=`Edit ${f.profile_key} form v${f.version}`;const byKey=Object.fromEntries(f.fields.map(x=>[x.field_key,x]));document.getElementById('fieldEditor').innerHTML=Object.keys(registry).map((key,i)=>{const x=byKey[key]||{field_key:key,is_enabled:0,is_required:0,prompt_am:'',prompt_en:'',help_am:'',help_en:''};return `<div class="card formField" data-key="${esc(key)}" style="margin-bottom:9px"><b>${esc(registry[key].label||key)}</b><div class="hint">${esc(key)}${['choice','dynamic_choice'].includes(registry[key].input)?' • Button choices':''}</div><div style="margin:7px 0"><label><input class="enabled" type="checkbox" ${x.is_enabled==1?'checked':''}> Enabled</label> <label><input class="required" type="checkbox" ${x.is_required==1?'checked':''}> Required</label></div><div class="form"><label class="field full">የቦት ጥያቄ<input class="promptAm" maxlength="500" value="${esc(x.prompt_am||'')}"></label><input class="promptEn" type="hidden" value="${esc(x.prompt_am||'')}"><label class="field full">አጭር መመሪያ<input class="helpAm" maxlength="500" value="${esc(x.help_am||'')}"></label><input class="helpEn" type="hidden" value="${esc(x.help_am||'')}"></div></div>`}).join('');formDlg.showModal()}function fieldPayload(){return [...document.querySelectorAll('.formField')].map(x=>({field_key:x.dataset.key,is_enabled:x.querySelector('.enabled').checked?1:0,is_required:x.querySelector('.required').checked?1:0,prompt_am:x.querySelector('.promptAm').value,prompt_en:x.querySelector('.promptAm').value,help_am:x.querySelector('.helpAm').value,help_en:x.querySelector('.helpAm').value}))}const previewDlg=document.getElementById('formPreviewDialog');function previewForm(){const fields=fieldPayload().filter(x=>x.is_enabled);if(!fields.length){showError(new Error('Enable at least one question before previewing.'));return}document.getElementById('formPreviewMeta').textContent=`${fields.length} enabled questions • ${fields.filter(x=>x.is_required).length} required • preview uses the current unsaved draft`;document.getElementById('formPreviewBody').innerHTML=fields.map((x,index)=>{const definition=registry[x.field_key]||{},help=x.help_am||'',optional=x.is_required?'':'\n\n/skip — ዝለል / skip this optional question',choices=['choice','dynamic_choice'].includes(definition.input)&&definition.choices?`<div class="bot-options">${Object.values(definition.choices).map(choice=>`<span>${esc(choice)}</span>`).join('')}</div>`:'';return `<div class="preview-meta">Question ${index+1} • ${esc(definition.label||x.field_key)} • ${x.is_required?'Required':'Optional'}</div><div class="bot-bubble">${esc(x.prompt_am)}${help?`\n\nℹ️ ${esc(help)}`:''}${optional}</div>${choices}`}).join('');previewDlg.showModal()}document.getElementById('previewForm').onclick=previewForm;document.getElementById('closeFormPreview').onclick=()=>previewDlg.close();async function saveForm(){const body=new FormData();body.set('action','form_save');body.set('csrf_token',CSRF);body.set('id',formEditor.elements.namedItem('id').value);body.set('title_am',formEditor.elements.namedItem('title_am').value);body.set('title_en',formEditor.elements.namedItem('title_am').value);body.set('fields_json',JSON.stringify(fieldPayload()));return api('form_save',{method:'POST',body})}formEditor.onsubmit=async e=>{e.preventDefault();try{await saveForm();formDlg.close();notify('Form draft saved.');await loadForms()}catch(x){showError(x)}};document.getElementById('cancelForm').onclick=()=>formDlg.close();document.getElementById('publishForm').onclick=async()=>{if(!(await tgConfirm({tier:'medium',title:'Publish this form version?',summary:'This version becomes immutable and replaces the currently published version for new drafts.',intent:'I reviewed the bilingual prompts and required fields',consequences:['New Telegram drafts use this version.','The previous published version is retired.'],keeps:['Existing drafts keep their original version.','No member records are changed.'],confirmLabel:'Publish version'})))return;try{await saveForm();const body=new FormData();body.set('action','form_publish');body.set('csrf_token',CSRF);body.set('id',formEditor.elements.namedItem('id').value);await api('form_publish',{method:'POST',body});formDlg.close();notify('The new form version is now published.');await loadForms()}catch(x){showError(x)}};document.querySelectorAll('.newForm').forEach(b=>b.onclick=async()=>{try{const body=new FormData();body.set('action','form_create');body.set('csrf_token',CSRF);body.set('profile_key',b.dataset.profile);const j=await api('form_create',{method:'POST',body});notify('A new editable form version was created.');await loadForms();await openForm(j.form.id)}catch(x){showError(x)}});<?php endif;?><?php endif;?>
<?php if($role==='super_admin'):?>const featureToggle=document.getElementById('featureToggle');featureToggle.onclick=async()=>{const enable=featureToggle.dataset.enabled!=='1',verb=enable?'enable':'disable';if(!(await tgConfirm({tier:'medium',title:`${enable?'Enable':'Disable'} Telegram registration?`,summary:enable?'The webhook will begin accepting authorized private registration messages after reload.':'The webhook will stop processing registration messages after reload.',intent:`I want to ${verb} Telegram registration`,consequences:[enable?'Authorized operators can start registration drafts.':'New Telegram updates are rejected while disabled.'],keeps:['Existing drafts and audit history remain stored.'],confirmLabel:`${enable?'Enable':'Disable'} feature`})))return;try{const body=new FormData();body.set('action','feature_toggle');body.set('csrf_token',CSRF);body.set('enabled',enable?'1':'0');await api('feature_toggle',{method:'POST',body});notify(`Telegram registration ${enable?'enabled':'disabled'}. Reloading…`);setTimeout(()=>location.reload(),900)}catch(e){showError(e)}};const botSetupForm=document.getElementById('botSetupForm');api('bot_config').then(j=>{botSetupForm.elements.namedItem('bot_username').value=j.bot.username||''}).catch(showError);botSetupForm.onsubmit=async e=>{e.preventDefault();if(!(await tgConfirm({tier:'medium',title:'Replace this deployment bot configuration?',object:'Telegram bot credentials',summary:'The new token becomes active after PHP reloads the private configuration.',intent:'I am configuring the bot for this deployment only',consequences:['The previous bot token stops working for this deployment.','The webhook must use the matching generated secret.'],keeps:['No token is stored in the database.','Other school deployments are unchanged.'],confirmLabel:'Save bot setup'})))return;try{const body=new FormData(e.target);body.set('action','bot_config_save');body.set('csrf_token',CSRF);await api('bot_config_save',{method:'POST',body});e.target.elements.namedItem('bot_token').value='';notify('Bot credentials saved securely. Reload once before verification.','ok','Bot setup saved');await loadOverview()}catch(x){showError(x)}};async function refreshWebhook(){try{const j=await api('webhook_status');document.getElementById('webhookInfo').textContent=`Webhook: ${j.webhook.url||'not active'} • pending ${j.webhook.pending_update_count} • connections ${j.webhook.max_connections}${j.webhook.last_error_message?' • last error: '+j.webhook.last_error_message:''}`}catch(e){document.getElementById('webhookInfo').textContent=e.message}}document.getElementById('verifyBot').onclick=async()=>{try{const body=new FormData();body.set('action','bot_verify');body.set('csrf_token',CSRF);const j=await api('bot_verify',{method:'POST',body});document.getElementById('botIdentity').textContent=`Verified @${j.identity.username} (ID ${j.identity.id})`;notify(`Verified @${j.identity.username}.`,'ok','Bot connected');await refreshWebhook()}catch(e){showError(e)}};document.getElementById('activateWebhook').onclick=async()=>{if(!(await tgConfirm({tier:'medium',title:'Activate this bot webhook?',summary:'Telegram will send private bot messages to this development deployment.',intent:'I verified the bot identity and deployment URL',consequences:['Telegram switches this bot from polling to the HTTPS webhook.','Pending updates remain queued.'],keeps:['Only message updates are requested.','No member is created directly.'],confirmLabel:'Activate webhook'})))return;try{const body=new FormData();body.set('action','webhook_set');body.set('csrf_token',CSRF);const j=await api('webhook_set',{method:'POST',body});document.getElementById('webhookInfo').textContent=`Webhook active: ${j.webhook.url} • pending ${j.webhook.pending_update_count}`;notify('Telegram is now connected to this HTTPS webhook.','ok','Webhook active');}catch(e){showError(e)}};refreshWebhook();document.getElementById('backfill').onclick=async()=>{const el=document.getElementById('backfillStatus');try{const body=new FormData();body.set('action','canonical_backfill');body.set('csrf_token',CSRF);body.set('limit','100');const j=await api('canonical_backfill',{method:'POST',body});el.textContent=` Processed ${j.backfill.processed}; next cursor ${j.backfill.next_cursor}; ${j.backfill.done?'complete':'more remain'}.`;notify(`Processed ${j.backfill.processed} member identities.${j.backfill.done?' Backfill is complete.':' More remain.'}`)}catch(e){showError(e)}};<?php endif;?>
document.querySelectorAll('dialog').forEach(dialog=>{if(!dialog.querySelector('.dialog-close')){const close=document.createElement('button');close.type='button';close.className='dialog-close';close.setAttribute('aria-label','ዝጋ');close.textContent='×';close.onclick=()=>dialog.close();dialog.prepend(close)}});
loadOverview().catch(showError);
</script></body></html>